      de: ["Gegründet im 15. Jahrhundert am Ufer des Wadi Hanifa.", "UNESCO-Welterbestätte seit dem Jahr 2010.", "Hauptstadt des Ersten Saudi-Staates von 1744 bis 1818.", "Der Salwa-Palast ist das größte Gebäude im Bezirk At-Turaif.", "Zerstört durch osmanische Truppen nach einer sechsmonatigen Belagerung.", "Zentrum der Verbreitung der Da'wa-Reformbewegung in Arabien."],
      hu: ["A 15. században alapították a Vádi Hanifa partján.", "2010 óta az UNESCO Világörökség része a helyszín.", "Az Első Szaúdi Állam fővárosa volt 1744 és 1818 között.", "A Szalva-palota az At-Turaif negyed legnagyobb épülete.", "Oszmán csapatok rombolták le egy hathónapos ostrom után.", "A Da'wa reformmozgalom elterjedésének központja volt Arábiában."],
      ro: ["Fondat în secolul al XV-lea pe malurile Wadi Hanifa.", "Sit al Patrimoniului Mondial UNESCO din anul 2010.", "Capitala Primului Stat Saudit între 1744 și 1818.", "Palatul Salwa este cea mai mare structură din districtul At-Turaif.", "Distrus de trupele otomane după un asediu de șase luni.", "Centrul de difuzare a mișcării de reformă Da'wa în Arabia."],
      en: ["Founded in the 15th century on the banks of Wadi Hanifa.", "UNESCO World Heritage site since the year 2010.", "Capital of the First Saudi State from 1744 to 1818.", "Salwa Palace is the largest and most important structure in the district.", "Destroyed by Ottoman forces following a six-month siege in 1818.", "Center for the spread of the Da'wa reform movement in Arabia."],
      es: ["1744: Pacto entre Mohammed ibn Saud y Mohammed ibn Abd al-Wahhab.", "Primera capital del Primer Estado Saudí.", "Destruida en 1818 por Ibrahim Bajá (Imperio Otomano).", "Estilo Najdi característico con ladrillos de barro.", "El palacio Salwa fue la residencia de la familia real.", "Hoy forma parte del megaproyecto Diriyah Gate."],
